int main(int argc,char** argv){try{EconomicSupplyPolicyCatalog catalog;EconomicSupplyPolicyDefinition author;author.id="authored";author.reward_per_unit=3;catalog.policies.insert(author.id,author);auto author_wire=dynamic_economy_codec::encode(catalog);auto& fields=*author_wire.find("policies")->find(author.id)->as<BoundaryValue::Dict>();fields.erase(std::remove_if(fields.begin(),fields.end(),[](const auto& row){return row.first=="reward_total";}),fields.end());auto original=author_wire;auto parsed=decode_economic_supply_policy_catalog(author_wire);check(parsed.ok&&!parsed.value.policies.find(author.id)->reward_total&&parsed.value.policies.find(author.id)->reward_per_unit==3,"authored omitted total means per-unit reward");check(compare_boundary(original,author_wire).exact(),"catalog normalization does not change input");auto explicit_null=dynamic_economy_codec::encode(catalog);auto nullable=decode_economic_supply_policy_catalog(explicit_null);check(nullable.ok&&!nullable.value.policies.find(author.id)->reward_total,"explicit null keeps per-unit mode");auto total=explicit_null;*total.find("policies")->find(author.id)->find("reward_total")=BoundaryValue{Integer{7}};*total.find("policies")->find(author.id)->find("reward_per_unit")=BoundaryValue{Integer{0}};auto fixed=decode_economic_supply_policy_catalog(total);check(fixed.ok&&fixed.value.policies.find(author.id)->reward_total==std::optional<Integer>{7}&&fixed.value.policies.find(author.id)->reward_per_unit==0,"explicit total survives catalog boundary");NeedPolicy terms;terms.id=terms.source_key=terms.semantic_key=terms.organization_id=terms.site_id=terms.inventory_id=terms.item_id=terms.template_id=terms.funding_wallet_id=terms.reward_wallet_id=terms.accept_role=terms.report_role="source";terms.max_claim_quantity=5;terms.purchase_budget_per_unit=6;terms.reward_per_unit=1;terms.deadline_ticks=24;check(validate_need_policy(terms).ok,"per-unit original policy valid");terms.reward_total=7;check(!validate_need_policy(terms).ok,"original policy still rejects mixed reward modes");terms.reward_per_unit=0;check(validate_need_policy(terms).ok,"original fixed-total policy valid");auto missing=author_wire;auto& required=*missing.find("policies")->find(author.id)->as<BoundaryValue::Dict>();required.erase(std::remove_if(required.begin(),required.end(),[](const auto& row){return row.first=="funding_wallet_id";}),required.end());check(!decode_economic_supply_policy_catalog(missing).ok,"required funding field stays strict");auto malformed=author_wire;malformed.find("policies")->find(author.id)->as<BoundaryValue::Dict>()->emplace_back("reward_total",BoundaryValue{"bad"});check(!decode_economic_supply_policy_catalog(malformed).ok,"wrong total type rejected");auto duplicate_catalog=author_wire;auto& duplicates=*duplicate_catalog.find("policies")->find(author.id)->as<BoundaryValue::Dict>();duplicates.emplace_back("reward_total",BoundaryValue{});duplicates.emplace_back("reward_total",BoundaryValue{});check(!decode_economic_supply_policy_catalog(duplicate_catalog).ok,"duplicate catalog optional rejected");EconomicSupplyPolicyState state;state.initialized_tick=2;state.last_observation_tick=4;EconomicSupplyPolicyRecord policy;policy.id="economic_supply_policy:4";policy.author_policy_id="policy.new";policy.registration_fact_id="political_takeover_pending:3";policy.original_source_key="supply.old";policy.original_source_fact_id="local_supply:1";policy.grant_id="grant.new";policy.authority={"north","office.new",2,"issuer"};policy.policy.id=policy.policy.source_key=policy.policy.semantic_key=policy.id;policy.policy.organization_id="north";policy.policy.site_id="site";policy.policy.inventory_id="stock";policy.policy.item_id="grain";policy.policy.max_claim_quantity=5;policy.policy.purchase_budget_per_unit=3;policy.policy.reward_total=7;policy.issued_tick=2;policy.earliest_effective_tick=3;policy.through_tick=12;policy.target_amount=20;state.policies.insert(policy.id,policy);LocalSupplyObservation observation;observation.id="economic_supply_observation:8";observation.tick=4;observation.observation={policy.id,"north","site","stock","grain",observation.id,20,2,3};state.observations.insert(observation.id,{policy.id,observation});auto wire=encode_economic_supply_policy_state(state);auto read=decode_economic_supply_policy_state(wire);check(read.ok&&compare_boundary(wire,encode_economic_supply_policy_state(read.value)).exact(),"exact new policy JSON roundtrip");auto missing_runtime=wire;auto& saved_fields=*missing_runtime.find("policies")->find(policy.id)->find("policy")->as<BoundaryValue::Dict>();saved_fields.erase(std::remove_if(saved_fields.begin(),saved_fields.end(),[](const auto& row){return row.first=="reward_total";}),saved_fields.end());check(!decode_economic_supply_policy_state(missing_runtime).ok,"runtime optional field cannot be omitted");auto duplicate=wire;duplicate.find("policies")->find(policy.id)->find("policy")->as<BoundaryValue::Dict>()->emplace_back("reward_total",BoundaryValue{Integer{99}});check(!decode_economic_supply_policy_state(duplicate).ok,"duplicate reward rejected");auto unknown=wire;*unknown.find("version")=BoundaryValue{Integer{2}};check(!decode_economic_supply_policy_state(unknown).ok,"unknown new version rejected");unknown=wire;*unknown.find("policies")->find(policy.id)->find("policy")->find("measure")=BoundaryValue{"outstanding_obligation"};check(!decode_economic_supply_policy_state(unknown).ok,"procurement cannot become wage debt");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);check(visit_economic_supply_policy_checkpoint(writer,state).ok&&writer.finish().ok,"new binary writes");const auto& input=bytes;CodecVisitor reader(input);EconomicSupplyPolicyState decoded;check(visit_economic_supply_policy_checkpoint(reader,decoded).ok&&reader.finish().ok&&compare_boundary(wire,encode_economic_supply_policy_state(decoded)).exact(),"new binary exact state");bytes.pop_back();const auto& broken=bytes;CodecVisitor truncated(broken);check(!visit_economic_supply_policy_checkpoint(truncated,decoded).ok||!truncated.finish().ok,"truncation rejected");if(argc==2){std::ifstream file(argv[1]);check(bool(file),"actual Installed input opens");std::ostringstream bytes;bytes<<file.rdbuf();auto prepared=parse_boundary_json(bytes.str());check(prepared.ok,"actual Installed JSON parses");std::vector<const BoundaryValue*> modules;std::function<void(const BoundaryValue&)> find=[&](const BoundaryValue& value){if(const auto* rows=value.as<BoundaryValue::Dict>()){for(const auto& row:*rows){if(row.first=="economic_supply_policies")modules.push_back(&row.second);find(row.second);}}else if(const auto* rows=value.as<BoundaryValue::Array>())for(const auto& row:*rows)find(row);};find(prepared.value);check(modules.size()==1,"one original Installed supply module");const auto* policies=modules[0]->find("policies");check(policies&&policies->as<BoundaryValue::Dict>()&&!policies->as<BoundaryValue::Dict>()->empty(),"actual authored policies exist");check(!policies->as<BoundaryValue::Dict>()->front().second.find("reward_total"),"original first-red input still omits total");const auto before=prepared.value;auto decoded_catalog=decode_economic_supply_policy_catalog(*modules[0]);check(decoded_catalog.ok,"actual Installed optional author decodes");check(compare_boundary(before,prepared.value).exact(),"actual Installed input not edited");}std::cout<<"supply policy codec "<<checks<<"/0; not a registered World\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
